#!/usr/bin/env bash
#
# PocketPills — handwritten prescription recognition, final state (v3).
#
# This installs COMPLETE FILES rather than applying a diff. The previous script
# hung because it tried to patch: your local tree already had v2 applied, so
# `git apply` failed, and macOS BSD `patch` then prompted "File to patch:" on
# /dev/tty with no visible output — which looks exactly like a freeze.
# Whole-file installs land on the same result whether you are starting from
# stock, v1, v2, or a half-applied tree.
#
# WHAT THIS FIXES (measured on real prescription-demo.webp pixels):
#   Segmentation split ROWS first and COLUMNS second. On a two-column page the
#   left column's ink (BP, SpO2, Diet) bridges every gap in the right column,
#   so all five medicines fused into ONE 492px crop. TrOCR reads only the first
#   line of what it is given, so three medicines never reached the parser.
#   Now: rows -> columns -> rows AGAIN inside each cell, plus valley-splitting
#   for touching lines. Verified 5/5 medicines land in their own crop.
#   Plus n-best beam decoding re-ranked against the formulary.
#
# Debug any scan:  localStorage.setItem("pp:rx-debug","1")  then rescan.
#
set -euo pipefail

grep -q '"pocketpills-redesign"' package.json 2>/dev/null || {
  echo "!! Run from the pocketpills repo root."; exit 1; }

BK=".rxfinal-backup-$(date +%Y%m%d-%H%M%S)"
echo ">> Backups -> ${BK}/"

install_file() {
  local path="$1" b64="$2"
  mkdir -p "${BK}/$(dirname "$path")" "$(dirname "$path")"
  [ -f "$path" ] && cp "$path" "${BK}/${path}"
  printf '%s' "$b64" | base64 -d > "$path"
  echo "   wrote $path"
}

F0_PATH="src/lib/rxLexicon.ts"
F0_B64=""
F1_PATH="src/lib/rxOcr.ts"
F1_B64=""
F2_PATH="src/lib/localHtr/lineSegments.ts"
F2_B64=""
F3_PATH="src/lib/localHtr/trocrWorker.ts"
F3_B64=""
F4_PATH="src/lib/localHtr/htrClient.ts"
F4_B64=""

echo ">> Installing 5 files"
install_file "$F0_PATH" "$F0_B64"
install_file "$F1_PATH" "$F1_B64"
install_file "$F2_PATH" "$F2_B64"
install_file "$F3_PATH" "$F3_B64"
install_file "$F4_PATH" "$F4_B64"

echo ">> Verifying (tsc)"
npx tsc -b --noEmit </dev/null
echo ">> Verifying (vite build)"
npx vite build </dev/null >/dev/null
echo ""
echo "Done — tree is now at the final v3 state."
echo "Backup: ${BK}"
echo "Rollback: cp -r ${BK}/src ./"
echo ""
echo "Tip: clear stale backups from the failed runs with:"
echo "  rm -rf .rxfix*-backup-*"
